    def _exportChildren(self, outfile, level, namespaceprefix_='unix-def:', namespacedef_='xmlns:unix-def="http://oval.mitre.org/XMLSchema/oval-definitions-5#unix" xmlns:oval-def="http://oval.mitre.org/XMLSchema/oval-definitions-5" ', name_='gconf_object', fromsubclass_=False, pretty_print=True):
        super(gconf_object, self)._exportChildren(outfile, level, namespaceprefix_, namespacedef_, name_, True, pretty_print=pretty_print)
        if pretty_print:
            eol_ = '\n'
        else:
            eol_ = ''
        if self.set_ is not None:
            namespaceprefix_ = self.set__nsprefix_ + ':' if (UseCapturedNS_ and self.set__nsprefix_) else ''
            self.set_.export(outfile, level, namespaceprefix_='oval-def:', namespacedef_='', name_='set', pretty_print=pretty_print)
