        self.original_tagname_ = None
        self.parent_object_ = kwargs_.get('parent_object_')
        self.ns_prefix_ = None
        super(globals().get("rpminfo_state"), self).__init__(id, version, operator, comment, deprecated, Signature, notes,  **kwargs_)
        self.name = name
        self.validate_EntityStateStringType(self.name)
        self.name_nsprefix_ = "oval-def"
        self.arch = arch
        self.validate_EntityStateStringType(self.arch)
        self.arch_nsprefix_ = "oval-def"
        self.epoch = epoch
        self.epoch_nsprefix_ = None
        self.release = release
        self.release_nsprefix_ = None
        self.version_ = version_
        self.version__nsprefix_ = None
        self.evr = evr
        self.validate_EntityStateEVRStringType(self.evr)
        self.evr_nsprefix_ = "oval-def"
        self.signature_keyid = signature_keyid
        self.validate_EntityStateStringType(self.signature_keyid)
        self.signature_keyid_nsprefix_ = "oval-def"
        self.extended_name = extended_name
        self.validate_EntityStateStringType(self.extended_name)
        self.extended_name_nsprefix_ = "oval-def"
