class package_object(ObjectType):
    """pkginst -- The pkginst entity is a string that represents a package designation by its instance. An instance can be the package abbreviation or a specific instance (for example, inst.1 or inst.2).
    
    """
    __hash__ = GeneratedsSuper.__hash__
    subclass = None
    superclass = ObjectType
    def __init__(self, id=None, version=None, comment=None, deprecated=False, Signature=None, notes=None, set_=None, pkginst=None, filter=None, gds_collector_=None, **kwargs_):
        self.gds_collector_ = gds_collector_
        self.gds_elementtree_node_ = None
        self.original_tagname_ = None
        self.parent_object_ = kwargs_.get('parent_object_')
        self.ns_prefix_ = "sol-def"
        super(globals().get("package_object"), self).__init__(id, version, comment, deprecated, Signature, notes,  **kwargs_)
        self.set_ = set_
        self.set__nsprefix_ = "oval-def"
        self.pkginst = pkginst
        self.validate_EntityObjectStringType(self.pkginst)
        self.pkginst_nsprefix_ = "oval-def"
        if filter is None:
            self.filter = []
        else:
            self.filter = filter
        self.filter_nsprefix_ = "oval-def"
    def factory(*args_, **kwargs_):
        if CurrentSubclassModule_ is not None:
            subclass = getSubclassFromModule_(
                CurrentSubclassModule_, package_object)
            if subclass is not None:
                return subclass(*args_, **kwargs_)
        if package_object.subclass:
            return package_object.subclass(*args_, **kwargs_)
        else:
            return package_object(*args_, **kwargs_)
    factory = staticmethod(factory)
    def get_ns_prefix_(self):
        return self.ns_prefix_
    def set_ns_prefix_(self, ns_prefix):
        self.ns_prefix_ = ns_prefix
    def get_set(self):
        return self.set_
    def set_set(self, set_):
        self.set_ = set_
    def get_pkginst(self):
        return self.pkginst
    def set_pkginst(self, pkginst):
        self.pkginst = pkginst
    def get_filter(self):
        return self.filter
